# Function to replace hex letters a–f with their decimal equivalents
def replace_alpha_with_decimal(hex_str):
    replacements = {
        'a': '10', 'b': '11', 'c': '12',
        'd': '13', 'e': '14', 'f': '15'
    }
    result = []
    for char in hex_str:
        if char.lower() in replacements:
            result.append(replacements[char.lower()])
